              "query": "Resources\n| where type =~ 'microsoft.azurearcdata/sqlserverinstances'\n| where tolower(tostring(properties.containerResourceId)) !contains '/providers/microsoft.compute/virtualmachines/'\n| extend expectedId=tolower(tostring(properties.containerResourceId))\n| extend containerKind=case(isempty(expectedId),'Missing',expectedId contains '/providers/microsoft.hybridcompute/machines/','Arc Machine',expectedId contains '/providers/microsoft.compute/virtualmachines/','Azure VM','Other')\n| join kind=leftouter (Resources | where type in~ ('microsoft.hybridcompute/machines') | project expectedId=tolower(id),foundId=id) on expectedId\n| where isempty(foundId) or containerKind in ('Missing','Other')\n| project id,category='Container',resourceName=name,serviceType=tostring(properties.serviceType),sqlVersion=tostring(properties.version),edition=tostring(properties.edition),sqlStatus=tostring(properties.status),provisioningState=tostring(properties.provisioningState),lastInventoryUploadTime=todatetime(properties.lastInventoryUploadTime),lastUsageUploadTime=todatetime(properties.lastUsageUploadTime),inventoryAgeDays=datetime_diff('day',now(),todatetime(properties.lastInventoryUploadTime)),resourceId=id,parentResourceId=expectedId,containerKind,finding=case(containerKind=='Missing',iff('{Language}'=='PT','containerResourceId ausente','Missing containerResourceId'),containerKind=='Other',iff('{Language}'=='PT','Tipo de contêiner desconhecido','Unknown container type'),iff('{Language}'=='PT','Contêiner ausente do ARG','Container absent from ARG')),rpValidation=iff('{Language}'=='PT','Pendente','Pending'),resourcePortalUrl=strcat('https://portal.azure.com/#resource',id),parentPortalUrl=iff(isnotempty(expectedId),strcat('https://portal.azure.com/#resource',expectedId),'')\n| order by resourceId asc",
